    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void transfer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody TransferForm form) {
        transfers.transfer(sheetId.trim(), user.trim(), personId, form.toSheet().trim());
    }

    private PersonView view(String sheet, Person person) {
        long personId = person.getId();
        return PersonView.of(person, claims.forPerson(sheet, personId), rates.table(sheet),
                statements.forPerson(sheet, personId), service.patrons(sheet, personId),
                service.clashing(sheet, person));
    }

    /** Another save took the name or contact first: the unique name or contact on the sheet refuses this one. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    private PersonView move(String sheetId, long claimId, String user, ClaimStatus next) {
        String sheet = sheetId.trim();
        return view(sheet, claims.move(sheet, user.trim(), claimId, next));
    }

    private PersonView view(String sheetId, long personId) {
        Person person = people.get(sheetId, personId);
        return PersonView.of(person, claims.forPerson(sheetId, personId),
                rates.table(sheetId), statements.forPerson(sheetId, personId), people.patrons(sheetId, personId),
                people.clashing(sheetId, person));
    }

    public PersonView addClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
