    private PersonView view(String sheetId, long personId) {
        Person person = people.get(sheetId, personId);
        return PersonView.of(person, claims.forPerson(sheetId, personId),
                rates.table(sheetId), statements.forPerson(sheetId, personId), people.patrons(sheetId, personId),
                people.clashing(sheetId, person));
    }

    public PersonView addClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody FromTemplateForm form) {
        String sheet = sheetId.trim();
        long id = templates.addClaim(sheet, user.trim(), personId, form.name());
        Person person = people.get(sheet, id);
        return PersonView.of(person, claims.forPerson(sheet, id), rates.table(sheet),
                statements.forPerson(sheet, id), people.patrons(sheet, id), people.clashing(sheet, person));
    }

